import 'package:flutter/material.dart';import '../data/app_store.dart';import '../localization/app_language.dart';import '../theme/operon_theme.dart';
class NotesScreen extends StatefulWidget{final AppStore store;const NotesScreen({super.key,required this.store});@override State<NotesScreen> createState()=>_S();}
class _S extends State<NotesScreen>{@override Widget build(BuildContext c){final items=[...widget.store.notes]..sort((a,b)=>a.pinned==b.pinned?b.createdAt.compareTo(a.createdAt):(a.pinned?-1:1));return Scaffold(appBar:AppBar(title:Text(c.tr.operatorNotes)),body:items.isEmpty?Center(child:Text(c.tr.noNotesYet)):ListView(children:items.map((n)=>Card(child:ListTile(leading:Icon(n.pinned?Icons.push_pin:Icons.note_alt_outlined,color:OperonTheme.teal),title:Text(n.title),subtitle:Text('${n.equipmentTag ?? c.tr.general}\n${n.body}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pin')widget.store.toggleNotePin(n);if(v=='done')widget.store.resolveNote(n);setState((){});},itemBuilder:(_)=>[PopupMenuItem(value:'pin',child:Text(c.tr.pinUnpin)),if(!n.resolved)PopupMenuItem(value:'done',child:Text(c.tr.resolve))])))).toList()),floatingActionButton:FloatingActionButton(onPressed:_add,child:const Icon(Icons.add)));}
void _add(){final title=TextEditingController(),body=TextEditingController(),tag=TextEditingController();showDialog(context:context,builder:(c)=>AlertDialog(title:Text(context.tr.operatorNote),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:InputDecoration(labelText:context.tr.title)),TextField(controller:tag,decoration:InputDecoration(labelText:context.tr.equipmentTag)),TextField(controller:body,maxLines:4,decoration:InputDecoration(labelText:context.tr.note))]),actions:[FilledButton(onPressed:(){widget.store.addNote(title.text,body.text,tag:tag.text.trim().isEmpty?null:tag.text.trim().toUpperCase());Navigator.pop(c);setState((){});},child:Text(context.tr.save))]));}}
